s.hostnames.create","parameters":[{"$ref":"#/components/parameters/IdempotencyKeyParam"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/CreateDomainHostnameRequest"}}},"required":true},"responses":{"201":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainHostnameResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Created"},"404":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源不存在"},"409":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源冲突"},"422":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"校验错误"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Create a hostname in a root domain zone","tags":["domain"],"x-sdkwork-idempotent":true}},"/app/v3/api/domain_zones/{zoneId}/hostnames/{hostnameId}":{"delete":{"operationId":"domainZones.hostnames.delete","parameters":[],"responses":{"204":{"description":"Deleted"},"404":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源不存在"},"409":{"content":{"application/problem+json":{"schema":{"$ref":"#/components/schemas/ProblemDetail"}}},"description":"资源冲突"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Delete an unbound domain hostname","tags":["domain"]},"get":{"operationId":"domainZones.hostnames.retrieve","parameters":[],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainHostnameResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Su