  ('f30748ab-1329-5c6c-932a-20ffbd3ea1e1', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'certificates.retrieve', 'GET', '/app/v3/api/certificates/{certificateId}', '获取证书详情', $sdkwork_catalog${"en-US":"获取证书详情"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["certificate"]$sdkwork_catalog$::jsonb, FALSE, 270),
  ('c683932d-430a-58dd-99e2-28e1130fc08e', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'certificates.delete', 'DELETE', '/app/v3/api/certificates/{certificateId}', '撤销证书', $sdkwork_catalog${"en-US":"撤销证书"}$sdkwork_catalog$::jsonb, '撤销证书生命周期聚合并停止自动续期；密钥材料由 Secret Manager/KMS 生命周期独立管理。', $sdkwork_catalog${"en-US":"撤销证书生命周期聚合并停止自动续期；密钥材料由 Secret Manager/KMS 生命周期独立管理。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["certificate"]$sdkwork_catalog$::jsonb, FALSE, 280),
  ('f20f0677-d29d-570a-8ce8-a9c239fbf168', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'certificates.renew', 'POST', '/app/v3/api/certificates/{certificateId}/renew', '计划托管证书续期', $sdkwork_catalog${"en-US":"计划托管证书续期"}$sdkwork_catalog$::jsonb, '仅适用于已激活且启用自动续期的托管证书；命令将续期状态原子调整为 PLANNED，由 ACME worker 领取。', $sdkwork_catalog${"en-US":"仅适用于已激活且启用自动续期的托管证书；命令将续期状态原子调整为 PLANNED，由 ACME worker 领取。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["certificate"]$sdkwork_catalog$::jsonb, FALSE, 290),
  ('90319490-8f1b-5ccf-ab0d-48a19ebdc66a', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'certificates.renewals.list', 'GET', '/app/v3/api/certificates/{certificateId}/renewals', '获取证书续期历史', $sdkwork_catalog${"en-US":"获取证书续期历史"}$sdkwork_catalog$::jsonb, '返回该证书的续期尝试台账，按创建时间倒序。每条记录保留本次尝试交接的 有效期窗口（previousNotBefore/previousNotAfter 与 newNotBefore/newNotAfter）， 因此证书被替换之后，「这个域名在某个时间段由哪张证书覆盖」仍然可以回答； 证书自身只保存当前状态，历史版本一旦被取代就无法从这里复原。', $sdkwork_catalog${"en-US":"返回该证书的续期尝试台账，按创建时间倒序。每条记录保留本次尝试交接的 有效期窗口（previousNotBefore/previousNotAfter 与 newNotBefore/newNotAfter）， 因此证书被替换之后，「这个域名在某个时间段由哪张证书覆盖」仍然可以回答； 证书自身只保存当前状态，历史版本一旦被取代就无法从这里复原。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["certificate"]$sdkwork_catalog$::jsonb, FALSE, 300),
