  ('cb4f7226-1353-5a33-9f7d-d60bd255c8be', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'uploadSessions.cancel', 'POST', '/app/v3/api/upload_sessions/{uploadSessionId}/cancel', '取消上传会话', $sdkwork_catalog${"en-US":"取消上传会话"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["uploadSession"]$sdkwork_catalog$::jsonb, FALSE, 340),
  ('5990e7f3-9c32-5d9c-9f04-12fb22772f6c', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'artifacts.list', 'GET', '/app/v3/api/artifacts', '获取租户制品列表', $sdkwork_catalog${"en-US":"获取租户制品列表"}$sdkwork_catalog$::jsonb, '包上传会话完成（packageType 1–5）后自动创建不可变制品记录。', $sdkwork_catalog${"en-US":"包上传会话完成（packageType 1–5）后自动创建不可变制品记录。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["artifact"]$sdkwork_catalog$::jsonb, FALSE, 350),
  ('ef8a5a54-c907-5dcf-8702-6d0698702d5d', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'artifacts.create', 'POST', '/app/v3/api/artifacts', 'Register a Drive-backed deployment artifact', $sdkwork_catalog${"en-US":"Register a Drive-backed deployment artifact"}$sdkwork_catalog$::jsonb, 'Registers immutable publishing metadata after the browser uploads bytes through the Drive App SDK. Deploy stores stable Drive references only and does not own presigned upload lifecycle.', $sdkwork_catalog${"en-US":"Registers immutable publishing metadata after the browser uploads bytes through the Drive App SDK. Deploy stores stable Drive references only and does not own presigned upload lifecycle."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["artifact"]$sdkwork_catalog$::jsonb, FALSE, 360),
  ('61ddd3e7-25c1-5bb0-9c8b-9a1fd2763f04', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'artifacts.retrieve', 'GET', '/app/v3/api/artifacts/{artifactId}', '获取制品详情', $sdkwork_catalog${"en-US":"获取制品详情"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["artifact"]$sdkwork_catalog$::jsonb, FALSE, 370),
  ('05d76a7f-b50c-5c64-9cb3-e8e20fce4f64', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'artifacts.delete', 'DELETE', '/app/v3/api/artifacts/{artifactId}', '保留并下架制品', $sdkwork_catalog${"en-US":"保留并下架制品"}$sdkwork_catalog$::jsonb, '将制品标记为 retained；Drive 节点生命周期仍由 Drive 管理。', $sdkwork_catalog${"en-US":"将制品标记为 retained；Drive 节点生命周期仍由 Drive 管理。"}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["artifact"]$sdkwork_catalog$::jsonb, FALSE, 380),
  ('adf6aeb2-8009-5491-a7af-91a3b4ef354c', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'apps.list', 'GET', '/app/v3/api/apps', 'List the apps the caller may reach', $sdkwork_catalog${"en-US":"List the apps the caller may reach"}$sdkwork_catalog$::jsonb, 'Returns the applications this subject can reach, which is the two tenant-wide ownership levels (`PLATFORM`, `TENANT`) plus their own personal apps and their organization''s apps. Reach is decided server-side from the request principal; `scope` can only narrow the page, never widen it.', $sdkwork_catalog${"en-US":"Returns the applications this subject can reach, which is the two tenant-wide ownership levels (`PLATFORM`, `TENANT`) plus their own personal apps and their organization's apps. Reach is decided server-side from the request principal; `scope` can only narrow the page, never widen it."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 390),
  ('57b5f973-f7ef-5a77-ba47-618eb815c038', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'apps.create', 'POST', '/app/v3/api/apps', 'Create a tenant app', $sdkwork_catalog${"en-US":"Create a tenant app"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 400),
