  ('effc84e8-ba49-553e-8f2d-ebbf74ef72ad', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'apps.activate', 'POST', '/app/v3/api/apps/{appId}/activate', '激活应用', $sdkwork_catalog${"en-US":"激活应用"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 430),
  ('7123e6a4-ae76-52f8-990c-a31f4caf0637', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'apps.domains.list', 'GET', '/app/v3/api/apps/{appId}/domains', 'List an app''s publishing domains', $sdkwork_catalog${"en-US":"List an app's publishing domains"}$sdkwork_catalog$::jsonb, 'Returns every hostname the app publishes on — the default `<appDomainLabel>.app[-<env>].<suffix>` hostnames across all lifecycle environments, plus the custom hostnames bound to the app — each with its binding state and, for custom hostnames, its DNS ownership verification state.', $sdkwork_catalog${"en-US":"Returns every hostname the app publishes on — the default `<appDomainLabel>.app[-<env>].<suffix>` hostnames across all lifecycle environments, plus the custom hostnames bound to the app — each with its binding state and, for custom hostnames, its DNS ownership verification state."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 440),
  ('2ebb14ee-72ad-57f2-a5e5-79ca3665bafd', 100001, '4d6de527-388b-59ad-9b07-deb040b20554', 'apps.composition.update', 'PUT', '/app/v3/api/apps/{appId}/composition', 'Replace and publish the complete live app composition', $sdkwork_catalog${"en-US":"Replace and publish the complete live app composition"}$sdkwork_catalog$::jsonb, 'Atomically replaces the normalized app composition, appends an immutable AppRevision, and enqueues complete runtime-set assignments. Live Drive or Knowledgebase content changes do not call this operation and do not create releases or deployments.', $sdkwork_catalog${"en-US":"Atomically replaces the normalized app composition, appends an immutable AppRevision, and enqueues complete runtime-set assignments. Live Drive or Knowledgebase content changes do not call this operation and do not create releases or deployments."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["app"]$sdkwork_catalog$::jsonb, FALSE, 450),
