  ('cce52b4d-4c33-5e38-8157-662cc2a87eac', 100001, 'ca97af96-2b00-52d8-82f0-da0283ddcb08', 'tlsOrders.advance', 'POST', '/backend/v3/api/tls/orders/{orderId}/advance', 'Advance a certificate order one canonical state machine step', $sdkwork_catalog${"en-US":"Advance a certificate order one canonical state machine step"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["tls"]$sdkwork_catalog$::jsonb, FALSE, 220),
