},"pageInfo":{"$ref":"#/components/schemas/PageInfo"}},"required":["items","pageInfo"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Revision history returned successfully."},"400":{"$ref":"#/components/responses/BadRequest"},"401":{"$ref":"#/components/responses/Unauthorized"},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"List an Nginx configuration's revisions","tags":["nginx"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-pagination-mode":"offset","x-sdkwork-permission":"web.nginx.write","x-sdkwork-request-context":"WebRequestContext"},"parameters":[{"in":"path","name":"configId","required":true,"schema":{"format":"uuid","type":"string"}},{"$ref":"#/components/parameters/PageParam"},{"$ref":"#/components/parameters/PageSizeParam"}]},"/backend/v3/api/nginx/etc/{configId}/revisions/{versionNo}":{"get":{"description":"Returns the immutable body captured for that version.","operationId":"configs.revisions.retrieve","responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/NginxConfigRevisionResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Revision returned successfully."},"401":{"$ref":"#/components/responses/Unauthorized"},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Retrieve one Nginx configuration revision","tags":["nginx"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.nginx.write","x-sdkwork-request-context":"WebRequestContext"},"parameters":[{"in":"path","name":"configId","required":true,"schema":{"format":"uuid","type":"string"}},{"in":"path","name":"versionNo","required":true,"schema":{"minimum":1,"type":"integer"}}]},"/backend/v3/api/nginx/etc/{configId}/revisions/{versionNo}/rollback":{"parameters":[{"in":"path","name":"configId","required":true,"schema":{"format":"uuid","type":"string"}},{"in":"path","name":"versionNo","required":true,"schema":{"minimum":1,"type":"integer"}}],"post":{"description":"Restores the selected revision body as a new revision and increments versionNo; history stays append-only.","operationId":"configs.revisions.rollback","responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/NginxConfigResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Configuration rolled back successfully."},"400":{"$ref":"#/components/responses/BadRequest"},"401":{"$ref":"#/components/responses/Unauthorized"},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Roll an Nginx configuration back to a revision","tags":["nginx"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.nginx.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/nginx/etc/{configId}/validate":{"parameters":[{"in":"path","name":"configId","required":true,"schema":{"format":"uuid","type":"string"}}],"post":{"operationId":"configs.validate","parameters":[],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/NginxValidateResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Nginx configuration validation result."}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Validate an Nginx configuration","tags":["nginx"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.nginx.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/nginx/reload":{"post":{"operationId":"reload","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/NginxReloadResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Nginx reload result."}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Reload Nginx","tags":["nginx"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.nginx.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/nginx/status":{"get":{"operationId":"status.retrieve","parameters":[],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/NginxStatusResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Nginx status returned successfully."}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Retrieve Nginx status","tags":["nginx"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.nginx.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/platform_metrics_summaries":{"get":{"description":"The dashboard's cardinal metrics over every tenant this edge serves, and the only reading that reports a **tenant count**: on the own-tenant operation that figure is structurally one.\nRestricted to the platform operator tenant: a tenant-bound context is rejected with 40301 rather than narrowed to its own slice, so a misrouted admin page fails loudly instead of presenting one tenant's estate as the platform's.\nReads across three owners - the IAM subjects, the metered usage facts, and the Web Server's own application table - and reports the capability as unavailable (`503`) when this deployment does not assemble all of them, because a count of zero and an inability to count are opposite claims that draw the same picture.\nA fourth owner is **optional**: the agents catalog is not declared by any topology profile, so a deployment that does not run the agents module still answers - with the agents metric named in `unassembledMetrics` rather than reported at `0`.\n`date_from` and `date_to` bound the **series** only; see the own-tenant operation for why that window is the caller's while the cards' are not.","operationId":"platformMetricsSummaries.retrieve","parameters":[{"description":"Inclusive UTC calendar day (`YYYY-MM-DD`) the per-day series starts on. Defaults to the trailing 30 days. The card windows ignore it.","in":"query","name":"date_from","schema":{"maxLength":10,"minLength":10,"type":"string"}},{"description":"Exclusive UTC calendar day (`YYYY-MM-DD`) the per-day series ends before. Defaults to tomorrow (UTC). The card windows ignore it.","in":"query","name":"date_to","schema":{"maxLength":10,"minLength":10,"type":"string"}}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/MetricsSummaryResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Dashboard metric summary returned successfully."}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Retrieve the dashboard metric summary of every tenant","tags":["metricsSummary"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.traffic.read","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/platform_traffic_usage":{"get":{"description":"Aggregates the traffic facts this edge recorded for every tenant it serves, and additionally fills the per-tenant breakdown. Restricted to the platform operator tenant: a tenant-bound context is rejected with 40301 rather than narrowed to its own slice, so a misrouted admin page fails loudly instead of rendering one tenant's traffic as the platform total.","operationId":"platformTrafficUsages.retrieve","parameters":[{"description":"Inclusive UTC calendar day (`YYYY-MM-DD`). Defaults to the trailing 30 days.","in":"query","name":"date_from","schema":{"maxLength":10,"minLength":10,"type":"string"}},{"description":"Exclusive UTC calendar day (`YYYY-MM-DD`). Defaults to tomorrow (UTC).","in":"query","name":"date_to","schema":{"maxLength":10,"minLength":10,"type":"string"}},{"description":"Restrict the totals and the series to one usage dimension.","in":"query","name":"dimension","schema":{"maxLength":64,"minLength":1,"type":"string"}},{"description":"Size of the per-app breakdown.","in":"query","name":"top_apps","schema":{"maximum":100,"minimum":1,"type":"integer"}}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/TrafficUsageStatisticsResponse"}},"required":["item"],"type":"object"}},"required":["data"],"type":"object"}]}}},"description":"Aggregated traffic usage returned successfully."}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Retrieve aggregated traffic usage of every tenant","tags":["trafficUsage"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.traffic.read","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/plugins":{"get":{"operationId":"plugins.list","parameters":[{"$ref":"#/components/parameters/PageParam"},{"$ref":"#/components/parameters/PageSizeParam"},{"in":"query","name":"status","schema":{"enum":["draft","active"],"type":"string"}},{"in":"query","name":"q","schema":{"maxLength":100,"type":"string"}},{"description":"Platform-operator review of another owner's catalog. Tenant-bound callers may not set it.","in":"query","name":"owner_id","schema":{"format":"int64","pattern":"^-?[0-9]+$","type":"string","x-sdkwork-int64-string":true}}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"items":{"items":{"$ref":"#/components/schemas/PluginResponse"},"type":"array"},"pageInfo":{"$ref":"#/components/schemas/PageInfo"}},"required":["items","pageInfo"],"type":"object"}},"type":"object"}]}}},"description":"Plugin catalog page returned successfully."}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"List the caller's plugin catalog","tags":["plugin"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-pagination-mode":"offset","x-sdkwork-permission":"web.plugins.read","x-sdkwork-request-context":"WebRequestContext"},"post":{"operationId":"plugins.create","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"requestBody