[{"$ref":"#/components/parameters/RootDomainIdParam"}],"patch":{"operationId":"rootDomains.update","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/UpdateRootDomainRequest"}}},"required":true},"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/RootDomainResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Tenant root-domain Zone updated successfully."},"404":{"$ref":"#/components/responses/NotFound"},"422":{"$ref":"#/components/responses/ValidationError"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Edit a tenant root-domain Zone","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/root_domains/{rootDomainId}/dns_records":{"get":{"description":"Pages the resolution-record snapshot the last cloud-account sync read from the provider: record type and record content (the resolution IP for A/AAAA, the target for CNAME/MX) per owner. The read never contacts the provider; `rootDomains.dnsRecords.sync` does that. A record whose owner matches no registered hostname still shows here at Zone scope; a record matched to a hostname deleted after the sync does not.","operationId":"rootDomains.dnsRecords.list","parameters":[{"$ref":"#/components/parameters/PageParam"},{"$ref":"#/components/parameters/PageSizeParam"},{"description":"Restrict the page to one registered subdomain by id. The sync has already applied the wildcard semantics when it stamped each record with its subdomain: a wildcard declaration's rows are its base owner and every owner beneath it, so the filter is one equality, not a name match.","in":"query","name":"domain_id","schema":{"format":"uuid","type":"string"}},{"description":"Restrict the page to records whose zone-relative owner (the record name) contains this keyword, case-insensitive: the search Aliyun's own DNS settings page offers.","in":"query","name":"host","schema":{"maxLength":253,"minLength":1,"type":"string"}},{"description":"Restrict the page to one record type (exact spelling, e.g. `A`).","in":"query","name":"record_type","schema":{"enum":["A","AAAA","CNAME","TXT","MX","NS","CAA"],"type":"string"}}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"items":{"items":{"$ref":"#/components/schemas/DomainDnsRecordResponse"},"type":"array"},"pageInfo":{"$ref":"#/components/schemas/PageInfo"}},"required":["items","pageInfo"],"type":"object"}},"type":"object"}]}}},"description":"Root-domain Zone resolution records returned successfully."},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"List a root-domain Zone's synced DNS resolution records","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-pagination-mode":"offset","x-sdkwork-permission":"web.applications.read","x-sdkwork-request-context":"WebRequestContext"},"parameters":[{"$ref":"#/components/parameters/RootDomainIdParam"}],"post":{"description":"Validates the change (type in the managed set, owner in the DNS label alphabet, value parsed per type) and writes it through the Zone's cloud account, then joins the vendor's answer to the stored snapshot. The owner is the zone-relative record name (`@`, `www`, `api.eu`, `*`); an owner already carrying the zone suffix is refused before the vendor is asked.","operationId":"rootDomains.dnsRecords.create","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/CreateDomainDnsRecordRequest"}}},"required":true},"responses":{"201":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainDnsRecordResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Resolution record created successfully."},"404":{"$ref":"#/components/responses/NotFound"},"422":{"$ref":"#/components/responses/ValidationError"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Create a resolution record through the Zone's cloud account","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/root_domains/{rootDomainId}/dns_records/sync":{"parameters":[{"$ref":"#/components/parameters/RootDomainIdParam"}],"post":{"description":"Re-reads the Zone's record inventory from its DNS provider through the Zone's cloud account: the bound account when one is pinned, otherwise the registered account whose zone covers the apex; and replaces the stored snapshot whole. Two syncs in a row answer with equivalent snapshots, so the operation is idempotent.","operationId":"rootDomains.dnsRecords.sync","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainDnsSyncResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Resolution records synced successfully."},"404":{"$ref":"#/components/responses/NotFound"},"422":{"$ref":"#/components/responses/ValidationError"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Sync a root-domain Zone's resolution records through its cloud account","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/root_domains/{rootDomainId}/dns_records/{recordId}":{"delete":{"description":"Deletes on the provider first and removes the stored row second, so a failed vendor delete never leaves a page serving a name the zone does not answer.","operationId":"rootDomains.dnsRecords.delete","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"responses":{"204":{"description":"Resolution record deleted successfully."},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Delete a resolution record through the Zone's cloud account","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-rate-limit-tier":"auth-critical","x-sdkwork-request-context":"WebRequestContext"},"parameters":[{"$ref":"#/components/parameters/RootDomainIdParam"},{"in":"path","name":"recordId","required":true,"schema":{"format":"uuid","type":"string"}}],"patch":{"description":"A full replace of owner/type/value/TTL (the update shape every integrated vendor shares), followed by the same replace in the stored snapshot. The provider-side pause state is not touched here; only the status operation flips it.","operationId":"rootDomains.dnsRecords.update","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/UpdateDomainDnsRecordRequest"}}},"required":true},"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainDnsRecordResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Resolution record updated successfully."},"404":{"$ref":"#/components/responses/NotFound"},"422":{"$ref":"#/components/responses/ValidationError"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Replace a resolution record in place through the Zone's cloud account","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/root_domains/{rootDomainId}/dns_records/{recordId}/status":{"parameters":[{"$ref":"#/components/parameters/RootDomainIdParam"},{"in":"path","name":"recordId","required":true,"schema":{"format":"uuid","type":"string"}}],"patch":{"description":"The provider is flipped first and the stored row second, so a failed vendor call never leaves the page claiming a state the vendor did not accept. A vendor without a per-record pause (Cloudflare) answers its own refusal.","operationId":"rootDomains.dnsRecords.status.update","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/DomainDnsRecordStatusRequest"}}},"required":true},"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainDnsRecordResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Resolution record status updated successfully."},"404":{"$ref":"#/components/responses/NotFound"},"422":{"$ref":"#/components/responses/ValidationError"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Pause a resolution record or resume it","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/root_domains/{rootDomainId}/subdomains":{"get":{"operationId":"rootDomains.subdomains.list","parameters":[{"$ref":"#/components/parameters/PageParam"},{"$ref":"#/components/parameters/PageSizeParam"}],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"items":{"items":{"$ref":"#/components/schemas/ApplicationDomainResponse"},"type":"array"},"pageInfo":{"$ref":"#/components/schemas/PageInfo"}},"required":["items","pageInfo"],"type":"object"}},"type":"object"}]}}},"description":"Root-domain hostnames returned successfully."},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"List publishable hostnames in a root-domain Zone","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-pagination-mode":"offset","x-sdkwork-permission":"web.applications.read","x-sdkwork-request-context":"WebRequestContext"},"parameters":[{"$ref":"#/components/parameters/RootDomainIdParam"}],"post":{"operationId":"rootDomains.subdomains.create","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/CreateRootDomainHostnameRequest"}}},"required":true},"responses":{"201":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/ApplicationDomainResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Root-domain hostname added successfully."},"404":{"$ref":"#/components/responses/NotFound"},"409":{"$ref":"#/components/responses/Conflict"},"422":{"$ref":"#/components/responses/ValidationError"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Add a publishable hostname to a root-domain Zone","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/root_domains/{rootDomainId}/verification_file":{"delete":{"operationId":"rootDomains.wechatVerification.delete","responses":{"204":{"description":"Verification file deleted successfully."},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Delete the root domain's WeChat verification file","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"},"get":{"description":"The platform-issued MP_verify_xxx.txt file this root domain publishes, if any. The edge serves it verbatim at https://<hostname>/<fileName> for the root domain's hostname and every registered subdomain under it; the apex row and a subdomain row manage the same file.","operationId":"rootDomains.wechatVerification.retrieve","responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainWechatVerificationResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Verification file state read successfully."},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Read the root domain's WeChat MP domain-ownership verification file","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.read","x-sdkwork-request-context":"WebRequestContext"},"parameters":[{"$ref":"#/components/parameters/RootDomainIdParam"}],"put":{"description":"Content is stored byte-exact: the platform compares bytes, so nothing is normalized. A fresh platform file replaces the previous one whole.","operationId":"rootDomains.wechatVerification.update","parameters":[{"$ref":"#/components/parameters/IdempotencyKey"}],"requestBody":{"content":{"application/json":{"schema":{"$ref":"#/components/schemas/UpsertDomainWechatVerificationRequest"}}},"required":true},"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainWechatVerificationResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Verification file stored successfully."},"404":{"$ref":"#/components/responses/NotFound"},"422":{"$ref":"#/components/responses/ValidationError"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Upload (or wholly replace) the root domain's WeChat verification file","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-idempotent":true,"x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/root_domains/{rootDomainId}/verification_file/check":{"parameters":[{"$ref":"#/components/parameters/RootDomainIdParam"}],"post":{"description":"Fetches https://<hostname>/<fileName> the way the WeChat crawler does (falling back to http to separate \"no TLS\" from \"no DNS\") and compares the body byte-for-byte with the stored file. Never throws: transport failures fold into the returned facts.","operationId":"rootDomains.wechatVerification.check","responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"properties":{"item":{"$ref":"#/components/schemas/DomainWechatVerificationCheckResponse"}},"required":["item"],"type":"object"}},"type":"object"}]}}},"description":"Probe outcome."},"404":{"$ref":"#/components/responses/NotFound"}},"security":[{"AccessToken":[],"AuthToken":[]}],"summary":"Self-check the root domain's WeChat verification file","tags":["domain"],"x-sdkwork-api-authority":"sdkwork-webserver-backend-api","x-sdkwork-api-surface":"backend-api","x-sdkwork-auth-mode":"dual-token","x-sdkwork-owner":"sdkwork-webserver","x-sdkwork-permission":"web.applications.write","x-sdkwork-request-context":"WebRequestContext"}},"/backend/v3/api/server_files/nodes":{"get":{"description":"Bounded-by-design collection (pagination exception, PAGINATION_SPEC section 11): the inventory is the managed deployment topology and is enforced to at most 100 nodes, so the list is served as one pagination-less page.","operationId":"serverFiles.nodes.list","parameters":[],"responses":{"200":{"content":{"application/json":{"schema":{"allOf":[{"$ref":"#/components/schemas/SdkWorkApiResponse"},{"properties":{"data":{"additionalP