  ('b9ca4ad1-af5d-505d-aca5-a3d2c092eeae', 100001, 'e85cd137-2363-54c1-bd4e-da7ce7c603ec', 'webserverConfigs.retrieve', 'GET', '/backend/v3/api/webserver_configs/{configId}', 'Read one managed configuration file', $sdkwork_catalog${"en-US":"Read one managed configuration file"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["webserverConfig"]$sdkwork_catalog$::jsonb, FALSE, 770),
  ('a2bae58d-4529-5a77-ac27-9faeec8b7453', 100001, 'e85cd137-2363-54c1-bd4e-da7ce7c603ec', 'webserverConfigs.update', 'PUT', '/backend/v3/api/webserver_configs/{configId}', 'Validate and atomically overwrite one managed configuration file', $sdkwork_catalog${"en-US":"Validate and atomically overwrite one managed configuration file"}$sdkwork_catalog$::jsonb, 'Creates a timestamped backup of the previous content, validates the new content (JSON/TOML parsers where applicable), and replaces the file atomically. Pass expectedSha256 from the preceding read for optimistic concurrency. This operation rewrites the live Web Server configuration plane and therefore requires the `web.nginx.write` permission (PRD-FR-029 route-level authorization).', $sdkwork_catalog${"en-US":"Creates a timestamped backup of the previous content, validates the new content (JSON/TOML parsers where applicable), and replaces the file atomically. Pass expectedSha256 from the preceding read for optimistic concurrency. This operation rewrites the live Web Server configuration plane and therefore requires the `web.nginx.write` permission (PRD-FR-029 route-level authorization)."}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["webserverConfig"]$sdkwork_catalog$::jsonb, FALSE, 780),
