  ('c1aac3fa-e4b2-58a5-8d48-2498dc9a5753', 100001, 'e85cd137-2363-54c1-bd4e-da7ce7c603ec', 'clusters.hosts.delete', 'DELETE', '/backend/v3/api/clusters/hosts/{hostId}', 'Remove an instance-free host from the cluster inventory', $sdkwork_catalog${"en-US":"Remove an instance-free host from the cluster inventory"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["cluster"]$sdkwork_catalog$::jsonb, FALSE, 910),
  ('42c736be-8d99-547d-91bf-e713acdc5052', 100001, 'e85cd137-2363-54c1-bd4e-da7ce7c603ec', 'clusters.instances.list', 'GET', '/backend/v3/api/clusters/instances', 'List webserver process instances with liveness state', $sdkwork_catalog${"en-US":"List webserver process instances with liveness state"}$sdkwork_catalog$::jsonb, '', $sdkwork_catalog${"en-US":""}$sdkwork_catalog$::jsonb, $sdkwork_catalog$["cluster"]$sdkwork_catalog$::jsonb, FALSE, 920),
